UPDATE acc_training_slides SET interactive_config = '{"type":"scenario","instruction":"You need to make the AE Detail Report form required whenever ''Adverse Event Occurred'' = Yes in the Visit form. How do you configure this?","data":{"context":"The Visit form has a Yes/No field called Adverse Event Occurred. When Yes is selected, you want the AE Detail Report form to automatically become required for this patient visit.","choices":[{"text":"Add a validation rule on Adverse Event Occurred","correct":false,"feedback":"Validation rules check values but cannot trigger other forms. You need Form Linking."},{"text":"Go to Branching Logic → Form Linking → set trigger field = Adverse Event Occurred, value = Yes, target = AE Detail Report","correct":true,"feedback":"Correct! Form Linking in Branching Logic connects fields in one form to requirements in another form."},{"text":"Add the AE Detail Report as required for all visits","correct":false,"feedback":"This would require it even when no AE occurred — unnecessary burden on coordinators."},{"text":"Create a workflow task to remind coordinators","correct":false,"feedback":"Manual reminders are unreliable. Form Linking automates the requirement based on the data."}]},"successMessage":"Form Linking is the correct approach for triggering forms based on field values!"}'
WHERE course_id = 19 AND order_index = 10;

