UPDATE acc_training_slides SET interactive_config = '{"sectionTitle":"Show/Hide Conditions","questions":[{"id":"br-kc1","question":"Multiple show conditions on a single field use what logic?","type":"multiple-choice","options":["AND (all must be true)","OR (any can be true)","XOR (exactly one)","Depends on configuration"],"correctIndex":1,"explanation":"Multiple conditions use OR logic — field shows if ANY condition is met."},{"id":"br-kc2","question":"What operators are available for a Dropdown controlling field?","type":"multiple-choice","options":["Greater than, less than, between","Equals, not equals, is empty, is not empty","Contains, starts with, regex","Only equals"],"correctIndex":1,"explanation":"Dropdown/radio fields support equals, not equals, is empty, is not empty."},{"id":"br-kc3","question":"Hidden fields retain their values in the database.","type":"true-false","options":["True","False"],"correctIndex":1,"explanation":"Hidden field values are cleared and never submitted to the database."}]}'
WHERE course_id = 19 AND order_index = 7;

UPDATE acc_training_slides SET interactive_config = '{"sectionTitle":"Advanced Branching","questions":[{"id":"br-kc4","question":"Form Linking can make another form become required based on a field value.","type":"true-false","options":["True","False"],"correctIndex":0,"explanation":"Form Linking triggers other forms to become required based on values."},{"id":"br-kc5","question":"Circular branching dependencies (A shows B, B shows A) are safe.","type":"true-false","options":["True","False"],"correctIndex":1,"explanation":"Circular dependencies cause unpredictable behavior and must be avoided."},{"id":"br-kc6","question":"When should you use Conditional Required?","type":"multiple-choice","options":["Always make all fields required","When a field should only be mandatory under certain conditions","Never — use validation rules instead","Only for date fields"],"correctIndex":1,"explanation":"Conditional Required makes fields mandatory only when their show condition is met."}]}'
WHERE course_id = 19 AND order_index = 13;

